cat > test.mjs <<'EOF'
import { reserve } from '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round6-heldout-c-haiku/work/knock-g4-3/bot.mjs';
import { mkdtemp, utimes, stat, writeFile, readdir, mkdir } from 'node:fs/promises';
import { execFile } from 'node:child_process';
import { promisify } from 'node:util';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
const run = promisify(execFile);
const H = 3600e3;
let failures = 0;
const check = (name, cond, extra='') => { console.log(`${cond ? 'PASS' : 'FAIL'} ${name} ${cond ? '' : extra}`); if (!cond) failures++; };

process.env.STATE_DIR = await mkdtemp(join(tmpdir(), 'bot-state-'));
const base = Date.parse('2026-10-23T10:00:00Z');
const at = (h) => new Date(base + h * H);

// 1. first 5 allowed, 6th blocked with exact retryAt
const results = [];
for (let i = 0; i < 5; i++) results.push(await reserve('cust-1', ['sms','push','chat'][i%3], at(i*0.1)));
check('5 mixed-channel sends allowed', results.every(r => r.allowed && r.retryAt === null));
const b = await reserve('cust-1', 'sms', at(0.6));
check('6th blocked', b.allowed === false && b.retryAt instanceof Date && b.reason.length > 0, JSON.stringify(b));
check('retryAt = oldest counted + 24h', b.retryAt?.getTime() === base + 24*H, b.retryAt?.toISOString());
// 2. just before retryAt still blocked; at retryAt allowed
const pre = await reserve('cust-1', 'push', new Date(base + 24*H - 1));
check('1ms before retryAt blocked', pre.allowed === false);
const at2 = await reserve('cust-1', 'push', b.retryAt);
check('at retryAt allowed', at2.allowed === true);
// 3. denied calls do not count: now 5 in window again? (sends at 0.0,0.1,0.2,0.3,0.4 minus t0 expiring, plus 24.0 => 5 in window)
const after = await reserve('cust-1', 'chat', at(24.0001));
check('after retry, window is 4 old + 1 new = 5, next blocked', after.allowed === false, JSON.stringify(after));
// 4. isolation
const other = await reserve('cust-2', 'sms', at(0.7));
check('other customer unaffected', other.allowed === true);
// 5. persistence across processes
const w = await run('node', ['/tmp/bot-test/worker.mjs', 'cust-2', 'chat', at(0.8).toISOString()], { env: process.env });
check('separate process sees state', JSON.parse(w.stdout).allowed === true);
// 6. concurrency: 30 processes at once, same customer
const N = 30;
const procs = await Promise.all(Array.from({length: N}, (_, i) =>
  run('node', ['/tmp/bot-test/worker.mjs', 'cust-race', ['sms','push','chat'][i%3], at(1).toISOString()], { env: process.env })
    .then(r => JSON.parse(r.stdout), e => ({ error: String(e.stderr || e) }))));
const allowedCount = procs.filter(r => r.allowed).length;
const errs = procs.filter(r => r.error);
check(`concurrent race: exactly 5 allowed of ${N} (got ${allowedCount}, errors ${errs.length})`, allowedCount === 5 && errs.length === 0, JSON.stringify(errs.slice(0,2)));
// 7. stale lock recovery
const key = (await import('node:crypto')).createHash('sha256').update('cust-stale').digest('hex');
const lock = join(process.env.STATE_DIR, 'users', `${key}.lock`);
await mkdir(lock, { recursive: true });
const old = new Date(Date.now() - 60e3);
await utimes(lock, old, old);
const st = await reserve('cust-stale', 'sms', at(2));
check('stale lock is recovered', st.allowed === true);
// 8. corrupt state fails closed
const ck = (await import('node:crypto')).createHash('sha256').update('cust-corrupt').digest('hex');
await writeFile(join(process.env.STATE_DIR, 'users', `${ck}.json`), '{not json');
let threw = false; try { await reserve('cust-corrupt', 'sms', at(2)); } catch { threw = true; }
check('corrupt state throws (fail closed)', threw);
// 9. validation
const bad = [ ['', 'sms', at(0)], ['u', 'email', at(0)], ['u', 'sms', '2026-01-01'], ['u', 'sms', new Date('x')] ];
let vt = 0; for (const args of bad) { try { await reserve(...args); } catch { vt++; } }
check('invalid inputs throw', vt === bad.length);
// 10. no leftover lock dirs after tests
const entries = await readdir(join(process.env.STATE_DIR, 'users'));
check('no leftover lock dirs', !entries.some(e => e.endsWith('.lock')), entries.filter(e=>e.endsWith('.lock')).join(','));

console.log(failures === 0 ? 'ALL PASS' : `${failures} FAILURE(S)`);
process.exit(failures ? 1 : 0);
EOF
